function legacyRewardFrequency(r={}){if(r.boxFrequency!=null||r.drawFrequency!=null)return normalizeFrequency(r.boxFrequency??r.drawFrequency,r.boxProbability);let rty=rarity(r.rarity);if(['MISTIC','LEGENDARY'].includes(rty))return'rare';if(['EPIC','RARE'].includes(rty))return'normal';return'common'}
