function eventFieldsFromChoice(ch,bag){['requiredFlags','blockedFlags','setFlags','removeFlags'].forEach(k=>split(ch&&ch[k]).forEach(x=>bag.add(x)))}
function collectEventIds(raw){let bag=new Set();Object.keys(raw.flags||{}).forEach(x=>bag.add(x));(raw.events||[]).forEach(e=>e&&e.id&&bag.add(e.id));(raw.thoughts||[]).forEach(t=>['requiredFlags','blockedFlags','flags'].forEach(k=>split(t&&t[k]).forEach(x=>bag.add(x))));(raw.gifts||[]).forEach(g=>['requiredFlags','blockedFlags','setFlags','removeFlags','choiceASetFlags','choiceARemoveFlags','choiceBSetFlags','choiceBRemoveFlags'].forEach(k=>split(g&&g[k]).forEach(x=>bag.add(x))));(raw.dialogues||raw.interactions||[]).forEach(sc=>{['requiredFlags','blockedFlags'].forEach(k=>split(sc&&sc[k]).forEach(x=>bag.add(x)));(sc.nodes||[]).forEach(n=>(n.choices||[]).forEach(ch=>eventFieldsFromChoice(ch,bag)))});return[...bag].filter(Boolean)}
function normalizeEvents(raw){let byId=new Map();(raw.events||raw.eventCatalog||[]).forEach(e=>{if(!e)return;let id=String(e.id||slug(e.name||e.title||'event','event')).trim();if(id)byId.set(id,{id,name:e.name||e.title||displayFromId(id),description:e.description||e.desc||'',hidden:!!e.hidden})});collectEventIds(raw).forEach(id=>{if(!byId.has(id))byId.set(id,{id,name:displayFromId(id),description:'',hidden:false})});return[...byId.values()].sort((a,b)=>a.name.localeCompare(b.name,'ko'))}
function collectMemoryTags(raw){let bag=new Set();(raw.memoryTagCatalog||[]).forEach(x=>bag.add(String(x)));(raw.memories||[]).forEach(m=>split(m&&m.tags).forEach(x=>bag.add(x)));(raw.thoughts||[]).forEach(t=>split(t&&t.requiredMemoryTags).forEach(x=>bag.add(x)));(raw.gifts||[]).forEach(g=>['requiredMemoryTags','memoryTags'].forEach(k=>split(g&&g[k]).forEach(x=>bag.add(x))));(raw.dialogues||raw.interactions||[]).forEach(sc=>{['requiredMemoryTags','blockedMemoryTags'].forEach(k=>split(sc&&sc[k]).forEach(x=>bag.add(x)));(sc.nodes||[]).forEach(n=>(n.choices||[]).forEach(ch=>['requiredMemoryTags','addMemoryTags'].forEach(k=>split(ch&&ch[k]).forEach(x=>bag.add(x)))))});return[...bag].filter(Boolean).sort((a,b)=>a.localeCompare(b,'ko'))}
function normalizeCategoryCatalog(raw,thoughts){let map=new Map(CATEGORY_DEFAULTS.map(c=>[c.id,{...c,locked:true}]));(raw.thoughtCategoryCatalog||[]).forEach(c=>{if(!c)return;let id=String(c.id||legacyCategoryId(c.label||c.name)||slug(c.label||c.name,'category'));if(id)map.set(id,{id,label:c.label||c.name||displayFromId(id),locked:!!c.locked})});(raw.thoughtCategories||[]).forEach(v=>{let id=legacyCategoryId(v);if(id&&!map.has(id))map.set(id,{id,label:String(v),locked:false})});(thoughts||[]).forEach(t=>{thoughtCategories(t).forEach(id=>{if(!map.has(id))map.set(id,{id,label:displayFromId(id),locked:false})});if(t.category){let id=legacyCategoryId(t.category);if(id&&!map.has(id))map.set(id,{id,label:String(t.category),locked:false})}});return[...map.values()]}
function mergeCollectionItems(canonical,legacy){let records=new Map(),anonymous=[];[...(Array.isArray(legacy)?legacy:[]),...(Array.isArray(canonical)?canonical:[])].forEach(item=>{if(!item||typeof item!=='object')return;let key=String(item.id||'').trim();if(!key){anonymous.push({...item});return}records.set(key,{...(records.get(key)||{}),...item})});return[...records.values(),...anonymous].map(i=>({...i,rarity:rarity(i.rarity)}))}
function migrateState(raw={}){let source=raw&&typeof raw==='object'?raw:{},s={...source},from=Number(source.thoughtSchemaVersion||0);if(from<1){let legacy=source.thoughtArchive||{};if(!Array.isArray(source.seenThoughtIds)&&Array.isArray(legacy.seen))s.seenThoughtIds=legacy.seen.slice();if(!Array.isArray(source.newThoughtIds)&&Array.isArray(legacy.new))s.newThoughtIds=legacy.new.slice()}if(from<2){s.events=Array.isArray(source.events)?source.events.slice():Array.isArray(source.eventCatalog)?source.eventCatalog.slice():[];s.memoryTagCatalog=Array.isArray(source.memoryTagCatalog)?source.memoryTagCatalog.slice():[]}if(from<3){s.thoughts=Array.isArray(source.thoughts)?source.thoughts.map(normalizeThought):[];s.thoughtCategoryCatalog=normalizeCategoryCatalog(source,s.thoughts)}if(from<4){let legacy=source.thoughtArchive||{},box=source.box||{};s.seenThoughtIds=uniqueTokens(source.seenThoughtIds,legacy.seen);s.newThoughtIds=uniqueTokens(source.newThoughtIds,legacy.new);s.collectionItems=mergeCollectionItems(source.collectionItems,source.items);s.ownedItems=uniqueTokens(source.ownedItems,source.owned);if(!source.settings?.mysteryBoxMode&&box.mode)s.settings={...(source.settings||{}),mysteryBoxMode:box.mode}}if(from<5)s.rewards=Array.isArray(source.rewards)?source.rewards.map(r=>({...r,boxFrequency:legacyRewardFrequency(r)})):[];if(from<6){let remaining=Number(source.thoughtRareCooldown?.remaining||0);s.thoughtRareCooldown={remaining:Number.isFinite(remaining)?Math.max(0,Math.floor(remaining)):0}}s.thoughtSchemaVersion=THOUGHT_SCHEMA_VERSION;return s}
function normalizeState(input={}){let raw=migrateState(input),s={...raw};s.settings={...DEFAULT_SETTINGS,...(raw.settings||{})};s.settings.thoughtAutoEnabled=s.settings.thoughtAutoEnabled!==false;s.settings.thoughtClickEnabled=s.settings.thoughtClickEnabled!==false;s.settings.thoughtPreferUnseen=s.settings.thoughtPreferUnseen!==false;s.settings.thoughtIntervalSeconds=clamp(s.settings.thoughtIntervalSeconds||60,10,3600);s.settings.mysteryBoxMode=s.settings.mysteryBoxMode==='unlimited'?'unlimited':'daily';s.characters=Array.isArray(raw.characters)?raw.characters:[];s.thoughts=Array.isArray(raw.thoughts)?raw.thoughts.map(normalizeThought):[];s.events=normalizeEvents({...raw,thoughts:s.thoughts});s.memoryTagCatalog=collectMemoryTags({...raw,thoughts:s.thoughts});s.thoughtCategoryCatalog=normalizeCategoryCatalog({...raw,thoughtCategoryCatalog:raw.thoughtCategoryCatalog},s.thoughts);let legacy=raw.thoughtArchive||{};s.seenThoughtIds=uniqueTokens(raw.seenThoughtIds,legacy.seen);s.newThoughtIds=uniqueTokens(raw.newThoughtIds,legacy.new);s.thoughtSeenAt=raw.thoughtSeenAt&&typeof raw.thoughtSeenAt==='object'?raw.thoughtSeenAt:{};s.thoughtArchive={...legacy,seen:s.seenThoughtIds.slice(),new:s.newThoughtIds.slice()};s.collectionItems=mergeCollectionItems(raw.collectionItems,raw.items);s.items=s.collectionItems.map(i=>({...i}));s.ownedItems=uniqueTokens(raw.ownedItems,raw.owned);s.owned=s.ownedItems.slice();s.newCollectionItems=Array.isArray(raw.newCollectionItems)?raw.newCollectionItems.slice():[];s.rewards=Array.isArray(raw.rewards)?raw.rewards.map(normalizeReward):[];s.memories=Array.isArray(raw.memories)?raw.memories:[];s.affection=raw.affection&&typeof raw.affection==='object'?raw.affection:{};s.moods=raw.moods||raw.mood||{};s.flags=raw.flags||{};s.box={lastDate:'',lastResult:null,history:[],...(raw.box||{})};if(!s.box.lastDate&&s.box.date)s.box.lastDate=s.box.date;if(!s.box.lastResult&&s.box.result)s.box.lastResult=s.box.result;if(s.box.lastResult)s.box.lastResult={...s.box.lastResult,rarity:rarity(s.box.lastResult.rarity)};s.box.history=Array.isArray(s.box.history)?s.box.history.map(x=>({...x,rarity:rarity(x.rarity)})):[];if(!Object.prototype.hasOwnProperty.call(s.box,'date'))s.box.date=s.box.lastDate;if(!Object.prototype.hasOwnProperty.call(s.box,'result'))s.box.result=s.box.lastResult;if(!Object.prototype.hasOwnProperty.call(s.box,'mode'))s.box.mode=s.settings.mysteryBoxMode;let rareRemaining=Number(raw.thoughtRareCooldown?.remaining||0);s.thoughtRareCooldown={remaining:Number.isFinite(rareRemaining)?Math.max(0,Math.floor(rareRemaining)):0};s.thoughtSchemaVersion=THOUGHT_SCHEMA_VERSION;return s}
function readState(){return normalizeState(readJSON(STATE_KEY,{}))}
function writeState(s,detail={}){let next=normalizeState(s);nativeWrite(STATE_KEY,JSON.stringify(next));window.dispatchEvent(new CustomEvent('hellaverse:state-updated',{detail:{source:'thought-archive',...detail}}));return next}
function updateState(fn,detail={}){let s=readState();fn(s);return writeState(s,detail)}
function readUI(){let u=readJSON(UI_KEY,{page:'',openThoughts:{}});return{page:u.page||'',openThoughts:u.openThoughts||{}}}
function writeUI(u){nativeWrite(UI_KEY,JSON.stringify(u))}
