function characterName(s,id){return(s.characters||[]).find(c=>c.id===id)?.name||''}
function eventName(s,id){return(s.events||[]).find(e=>e.id===id)?.name||displayFromId(id)}
function categoryLabel(s,id){return(s.thoughtCategoryCatalog||[]).find(c=>c.id===id)?.label||CATEGORY_DEFAULTS.find(c=>c.id===id)?.label||displayFromId(id)}
function moodLabel(id){return MOOD_CATALOG.find(m=>m.id===normalizeMoodId(id))?.label||displayFromId(id)}
function aff(s,cid){return clamp(s.affection?.[cid]?.value)}
function currentMood(s,cid){return normalizeMoodId(s.moods?.[cid]||'normal')||'normal'}
function hasFlags(s,v){return split(v).every(f=>s.flags&&s.flags[f])}
function hasBlocked(s,v){return split(v).some(f=>s.flags&&s.flags[f])}
function memoryTags(s,cid,v){let need=split(v);if(!need.length)return true;let own=new Set((s.memories||[]).filter(m=>m.characterId===cid&&!m.hidden).flatMap(m=>Array.isArray(m.tags)?m.tags:split(m.tags)));return need.every(x=>own.has(x))}
function matchesMood(t,mood){let moods=thoughtMoods(t);return!moods.length||moods.includes(normalizeMoodId(mood))}
function thoughtAvailable(s,t,cid=t.characterId){if(!t||t.characterId!==cid)return false;if(aff(s,cid)<Number(t.requiredAffection||0))return false;if(!matchesMood(t,currentMood(s,cid)))return false;if(t.requiredFlags&&!hasFlags(s,t.requiredFlags))return false;if(t.blockedFlags&&hasBlocked(s,t.blockedFlags))return false;if(t.requiredMemoryTags&&!memoryTags(s,cid,t.requiredMemoryTags))return false;return!!String(t.text||'').trim()}
function rollFrequency(){let n=Math.random()*100;if(n<FREQUENCY_RATES.common)return'common';if(n<FREQUENCY_RATES.common+FREQUENCY_RATES.normal)return'normal';return'rare'}
function pickWithinFrequency(s,list){if(!list.length)return null;let seen=new Set(s.seenThoughtIds||[]),unseen=list.filter(t=>!seen.has(t.id)),pool=s.settings.thoughtPreferUnseen!==false&&unseen.length?unseen:list;return pool[Math.floor(Math.random()*pool.length)]||null}
function chooseThought(s,cid){let eligible=s.thoughts.filter(t=>thoughtAvailable(s,t,cid));if(!eligible.length)return null;let buckets={common:[],normal:[],rare:[]};eligible.forEach(t=>buckets[normalizeFrequency(t.frequency,t.probability)].push(t));let wanted=rollFrequency(),cooldown=Number(s.thoughtRareCooldown?.remaining||0);if(wanted==='rare'&&cooldown>0)wanted='normal';let order=wanted==='rare'?['rare','normal','common']:wanted==='normal'?['normal','common']:['common','normal'];for(let key of order){let picked=pickWithinFrequency(s,buckets[key]);if(picked)return picked}return null}
function toast(message,detail='',duration=2300){let root=$('#toastRoot')||document.body,box=document.createElement('div');box.className='toast thought-toast';box.innerHTML=`<strong>${esc(message)}</strong>${detail?`<span>${esc(detail)}</span>`:''}`;root.innerHTML='';root.appendChild(box);setTimeout(()=>{if(box.parentNode)box.remove()},duration)}
function recordThoughtDisplay(t){let first=false;updateState(s=>{if(!s.seenThoughtIds.includes(t.id)){s.seenThoughtIds.push(t.id);s.newThoughtIds.push(t.id);s.thoughtSeenAt[t.id]=new Date().toISOString();first=true}s.thoughtArchive={seen:s.seenThoughtIds.slice(),new:s.newThoughtIds.slice()};let freq=normalizeFrequency(t.frequency,t.probability),remaining=Number(s.thoughtRareCooldown?.remaining||0);s.thoughtRareCooldown={remaining:freq==='rare'?RARE_THOUGHT_COOLDOWN:Math.max(0,remaining-1)}});return first}
function showCharacterThought(cid,trigger='click'){let s=readState();if(trigger==='click'&&s.settings.thoughtClickEnabled===false)return;if(trigger==='auto'&&s.settings.thoughtAutoEnabled===false)return;let t=chooseThought(s,cid);if(!t){if(trigger==='click')toast('NO THOUGHT AVAILABLE','현재 조건에서 볼 수 있는 Thought가 없습니다.');return}let line=pickLine(t.text)||t.text,first=recordThoughtDisplay(t),freq=normalizeFrequency(t.frequency,t.probability);toast(first&&freq==='rare'?'RARE THOUGHT DISCOVERED':first?'NEW THOUGHT DISCOVERED':'THOUGHT',line,first&&freq==='rare'?3200:2300);scheduleAutoThought(true)}
let autoTimer=0,lastAutoKey='',clickCooldown=0;
function scheduleAutoThought(force=false){clearTimeout(autoTimer);let s=readState(),u=readUI();if(u.page)return;let shell=$('.site-shell');if(!shell)return;let isHome=s.page==='home'||shell.classList.contains('page-home'),isRoom=s.page==='life'||shell.classList.contains('page-life');if(!isHome&&!isRoom||s.settings.thoughtAutoEnabled===false)return;let cid=isRoom?s.active:(s.homeCharacter||s.active);if(!cid)return;let key=(isRoom?'life':'home')+':'+cid;if(!force&&lastAutoKey===key&&autoTimer)return;lastAutoKey=key;autoTimer=setTimeout(()=>{autoTimer=0;showCharacterThought(cid,'auto')},Math.max(10,Number(s.settings.thoughtIntervalSeconds||60))*1000)}
function itemTitle(i){return i?.name||i?.title||'Item'}
function itemDesc(i){return i?.desc||i?.description||i?.memo||i?.body||''}
function countCollection(s,cid){let all=s.collectionItems.filter(i=>i.characterId===cid),own=all.filter(i=>s.ownedItems.includes(i.id));return{all:all.length,owned:own.length,p:all.length?Math.round(own.length/all.length*100):0}}
function countThoughts(s,cid){let all=s.thoughts.filter(t=>t.characterId===cid),seen=all.filter(t=>s.seenThoughtIds.includes(t.id));return{all:all.length,seen:seen.length,p:all.length?Math.round(seen.length/all.length*100):0}}
function patchNav(){let s=readState(),u=readUI(),nav=$('.main-nav');if(nav){let active=u.page||s.page,thought=$('[data-open-thoughts]',nav);if(!thought){thought=document.createElement('button');thought.type='button';thought.className='nav-button';thought.dataset.openThoughts='';thought.textContent='THOUGHTS';let anchor=$('[data-hv-missions],[data-page="settings"],[data-hv-settings-rescue]',nav);if(anchor)nav.insertBefore(thought,anchor);else nav.appendChild(thought)}let copies=$$('[data-open-thoughts]',nav);copies.slice(1).forEach(x=>x.remove());thought.classList.toggle('active',active==='thoughts');if(active==='thoughts')$$('.nav-button',nav).forEach(b=>{if(b!==thought)b.classList.remove('active')});$$('[data-open-mystery]',nav).forEach(x=>x.remove())}$$('[data-open-box]').forEach(b=>{if(b.closest('.home-quickbar'))b.remove()})}
function patchHome(){let s=readState(),quick=$('.home-quickbar');if(!quick)return;let cid=s.homeCharacter||s.active,cc=countCollection(s,cid),tc=countThoughts(s,cid),mc=(s.memories||[]).filter(m=>m.characterId===cid&&!m.hidden).length;quick.innerHTML=`<button data-page="collection">COLLECTION ${cc.owned}/${cc.all}</button><button data-open-thoughts>THOUGHTS ${tc.seen}/${tc.all}</button><button data-memories="${esc(cid)}">MEMORIES ${mc}</button>`}
