function replacePage(html,klass){let main=$('.site-shell');if(main)main.className='site-shell page-'+klass;let page=$('.page.active');if(page)page.innerHTML=html;$$('.page-head').forEach(x=>x.remove());patchNav()}
function renderThoughtPage(){let s=readState(),u=readUI(),groups=s.characters.filter(c=>!c.hidden&&s.thoughts.some(t=>t.characterId===c.id));replacePage(`<section class="thought-page"><header class="reward-page-head"><p>Character inner archive</p><h1>THOUGHTS</h1><span>캐릭터 화면에서 실제로 본 생각만 기록됩니다.</span></header><div class="collection-actions"><button class="text-link danger" data-reset-thoughts>RESET THOUGHT ARCHIVE</button></div>${groups.length?groups.map(c=>thoughtGroup(s,u,c)).join(''):'<section class="empty-state page-empty"><h2>No thoughts yet.</h2><p>EDITOR에서 Thought를 작성하면 이곳에 기록됩니다.</p></section>'}</section>`,'thoughts')}
function thoughtGroup(s,u,c){let all=s.thoughts.filter(t=>t.characterId===c.id),seen=all.filter(t=>s.seenThoughtIds.includes(t.id)),open=!!u.openThoughts[c.id],p=all.length?Math.round(seen.length/all.length*100):0;return`<section class="thought-group"><button class="thought-summary" data-thought-group="${esc(c.id)}"><span><strong>${esc(c.name)}</strong><em>${seen.length} / ${all.length} DISCOVERED</em></span>${progressBlock(p,`${seen.length} / ${all.length}`)}<b>${open?'v':'>'}</b></button>${open?`<div class="thought-grid">${all.map(t=>thoughtCard(s,t)).join('')}</div>`:''}</section>`}
function categoryText(s,t){let cats=thoughtCategories(t).map(id=>categoryLabel(s,id));return cats.length?cats.join(' · '):'분류 없음'}
function thoughtConditionLabel(s,t,seen){if(seen)return`HEART ${Number(t.requiredAffection||0)} · ${FREQUENCY_LABELS[normalizeFrequency(t.frequency,t.probability)]}`;if(t.requiredFlags||t.blockedFlags||t.requiredMemoryTags)return'LOCKED · ???';return`LOCKED · HEART ${Number(t.requiredAffection||0)}`}
function thoughtCard(s,t){let seen=s.seenThoughtIds.includes(t.id),nw=seen&&s.newThoughtIds.includes(t.id);return`<button class="thought-card ${seen?'seen':'locked'}" data-thought-card="${esc(t.id)}">${nw?'<em>NEW</em>':''}<small>${esc(thoughtConditionLabel(s,t,seen))}</small><strong>${esc(seen?categoryText(s,t):'???')}</strong><p>${esc(seen?short(t.text,180):'아직 발견하지 못한 생각입니다.')}</p></button>`}
function showThoughtDetail(id){let s=readState(),t=s.thoughts.find(x=>x.id===id);if(!t)return;let c=s.characters.find(x=>x.id===t.characterId)||{},seen=s.seenThoughtIds.includes(id);if(seen)updateState(x=>{x.newThoughtIds=x.newThoughtIds.filter(v=>v!==id);x.thoughtArchive={seen:x.seenThoughtIds.slice(),new:x.newThoughtIds.slice()}});let date=s.thoughtSeenAt?.[id]?new Date(s.thoughtSeenAt[id]).toLocaleString('ko-KR'):'';showModal(`<div class="thought-detail"><p class="label">${esc(c.name||'CHARACTER')}</p><h2>${esc(seen?categoryText(s,t):'???')}</h2><p class="status-label">${esc(thoughtConditionLabel(s,t,seen))}</p><blockquote>${esc(seen?t.text:'아직 발견하지 못한 생각입니다.')}</blockquote>${seen?`<p class="muted">DISCOVERED${date?' · '+esc(date):''}</p>`:''}</div>`)}
function renderMysteryPage(){let s=readState(),opened=s.settings.mysteryBoxMode!=='unlimited'&&s.box.lastDate===today(),last=s.box.lastResult;replacePage(`<section class="mystery-page"><header class="reward-page-head"><p>Independent reward draw</p><h1>MYSTERY BOX</h1><span>전체 Reward Pool에서 Draw Frequency를 먼저 뽑고 그 그룹 안에서 Reward를 선택합니다.</span><small>COMMON 89% · NORMAL 10% · RARE 1%</small></header><section class="box-stage"><div class="box-orb"><span>${opened?'OPENED':'READY'}</span></div><div class="box-actions"><h2>DAILY MYSTERY BOX</h2><p>${s.settings.mysteryBoxMode==='unlimited'?'TEST MODE · repeat available':'오늘의 보상을 확인하세요.'}</p>${opened&&last?`<button class="gold-button" data-view-last-box>VIEW TODAY'S RESULT</button>`:`<button class="gold-button" data-box-page-open>OPEN BOX</button>`}</div></section><section class="box-stats"><span><b>${s.rewards.length}</b>Available Rewards</span><span><b>${s.collectionItems.length}</b>Collection Items</span><span><b>${s.rewards.filter(r=>String(r.body||'').trim()).length}</b>Character Messages</span></section><details class="box-settings"><summary>BOX SETTINGS</summary><div class="mode-toggle"><button class="${s.settings.mysteryBoxMode!=='unlimited'?'active':''}" data-box-mode-v35="daily">DAILY MODE</button><button class="${s.settings.mysteryBoxMode==='unlimited'?'active':''}" data-box-mode-v35="unlimited">TEST MODE</button></div><button class="ghost-button danger" data-reset-box>RESET MYSTERY BOX</button></details>${boxHistory(s)}</section>`,'mystery')}
function boxHistory(s){return`<section class="box-history-page"><p class="label">HISTORY</p>${s.box.history.length?s.box.history.slice(0,20).map(x=>`<button class="history-row"><span>${esc(x.date||'')}</span><strong>${esc(x.title||'Reward')}</strong><em>${esc(x.characterName||characterName(s,x.characterId)||'')} · ${esc(rarity(x.rarity))}${x.duplicate?' · DUPLICATE':''}</em></button>`).join(''):'<p class="empty-state">아직 Mystery Box 기록이 없습니다.</p>'}</section>`}
function showModal(html){let root=$('#modalRoot')||document.body;root.innerHTML=`<div class="modal-backdrop" data-modal-close><section class="modal-card" onclick="event.stopPropagation()">${html}<button class="modal-close" data-modal-close>×</button></section></div>`}
function rewardModal(snap){showModal(`<div class="reward-reveal rarity-${rarity(snap.rarity).toLowerCase()}"><p class="rarity-label">${esc(rarity(snap.rarity))}</p><h2>${esc(snap.title||'Reward')}</h2><p class="character-name">${esc(snap.characterName||'')}</p>${snap.rewardBody?`<blockquote>${esc(snap.rewardBody)}</blockquote>`:''}${snap.itemDescription?`<p>${esc(snap.itemDescription)}</p>`:''}<p class="status-label">${snap.duplicate?'DUPLICATE · Already in your collection.':snap.isNew?'NEW COLLECTION ITEM':'REWARD'}</p><div class="button-row"><button class="gold-button" data-page="collection">VIEW COLLECTION</button><button class="ghost-button" data-modal-close>CLOSE</button></div></div>`)}
function pickMysteryReward(s){let buckets={common:[],normal:[],rare:[]};s.rewards.forEach(r=>buckets[normalizeFrequency(r.boxFrequency)].push(r));let wanted=rollFrequency(),order=wanted==='rare'?['rare','normal','common']:wanted==='normal'?['normal','common']:['common','normal'];for(let key of order){let list=buckets[key];if(list.length)return list[Math.floor(Math.random()*list.length)]}return null}
function openMysteryBox(){let s=readState();if(s.settings.mysteryBoxMode!=='unlimited'&&s.box.lastDate===today()&&s.box.lastResult){rewardModal(s.box.lastResult);return}if(!s.rewards.length){toast('NO REWARD','EDITOR에서 Mystery Box Reward를 먼저 작성해주세요.');return}let reward=pickMysteryReward(s);if(!reward){toast('NO REWARD','현재 Frequency 조건에서 뽑을 수 있는 Reward가 없습니다.');return}let item=reward.itemId?s.collectionItems.find(i=>i.id===reward.itemId):null,cid=reward.characterId||item?.characterId||s.active,c=s.characters.find(x=>x.id===cid)||{},dup=!!item&&s.ownedItems.includes(item.id),snap={id:uid('box'),date:now(),rewardId:reward.id,itemId:item?.id||'',characterId:cid,characterName:c.name||'',title:item?itemTitle(item):(reward.title||reward.name||'Reward'),rarity:rarity(item?.rarity||reward.rarity),rewardBody:pickLine(reward.body||reward.message)||reward.body||reward.message||'',itemDescription:item?itemDesc(item):'',duplicate:dup,isNew:!!item&&!dup};if(item&&!dup){s.ownedItems.push(item.id);s.owned=[...s.ownedItems];s.newCollectionItems.push(item.id)}s.box={...(s.box||{}),lastDate:today(),date:today(),lastResult:snap,result:snap,history:[snap,...(s.box.history||[])].slice(0,20)};writeState(s);rewardModal(snap)}
function resetCollectionProgress(){let ui=readJSON(MAIN_UI_KEY,{});ui.seenCollectionItems=[];nativeWrite(MAIN_UI_KEY,JSON.stringify(ui));updateState(s=>{s.ownedItems=[];s.owned=[];s.newCollectionItems=[]});toast('COLLECTION RESET','Collection 진행률이 0부터 다시 시작됩니다.')}
function resetThoughtArchive(){updateState(s=>{s.seenThoughtIds=[];s.newThoughtIds=[];s.thoughtSeenAt={};s.thoughtArchive={seen:[],new:[]}});toast('THOUGHT ARCHIVE RESET','작성한 Thought는 삭제되지 않았습니다.');if($('.thought-page'))renderThoughtPage()}
function resetMysteryBox(){updateState(s=>{s.box={...(s.box||{}),lastDate:'',date:'',lastResult:null,result:null,history:[]}});toast('MYSTERY BOX RESET','바로 다시 열 수 있습니다.');if($('.mystery-page'))renderMysteryPage()}
function resetModal(type){if(type==='collection')return showModal(`<p class="label">RESET COLLECTION</p><h2>Reset Collection?</h2><p>획득했던 모든 Collection Item을 잃고 처음부터 다시 수집합니다.</p><p>작성해둔 Item과 Reward 설정은 삭제되지 않습니다. Mystery Box와 Thought 기록은 초기화되지 않습니다.</p><div class="button-row"><button class="gold-button danger" data-confirm-reset-collection>RESET COLLECTION</button><button class="ghost-button" data-modal-close>CANCEL</button></div>`);if(type==='thought')return showModal(`<p class="label">RESET THOUGHT ARCHIVE</p><h2>Reset Thought Archive?</h2><p>지금까지 발견한 Thought 기록을 모두 초기화합니다.</p><p>작성한 Thought와 캐릭터 설정은 삭제되지 않습니다.</p><div class="button-row"><button class="gold-button danger" data-confirm-reset-thoughts>RESET THOUGHTS</button><button class="ghost-button" data-modal-close>CANCEL</button></div>`);if(type==='box')return showModal(`<p class="label">RESET MYSTERY BOX</p><h2>Reset Mystery Box?</h2><p>오늘의 뽑기 상태와 Mystery Box 기록만 초기화합니다.</p><div class="button-row"><button class="gold-button danger" data-confirm-reset-box>RESET</button><button class="ghost-button" data-modal-close>CANCEL</button></div>`)}
function switchButton(key,label,desc,on){return`<div class="toggle-row"><span><strong>${esc(label)}</strong><small>${esc(desc)}</small></span><button type="button" class="toggle-switch ${on?'on':'off'}" data-thought-toggle="${key}" aria-pressed="${on?'true':'false'}"><i></i><b>${on?'ON':'OFF'}</b></button></div>`}
function patchSettings(){let s=readState(),grid=$('.settings-grid');if(!grid)return;$$('[data-thought-settings]').forEach(x=>x.remove());let panel=document.createElement('section');panel.className='settings-panel thought-settings-card';panel.dataset.thoughtSettings='yes';let preset=[30,60,120,180,300].includes(Number(s.settings.thoughtIntervalSeconds))?String(s.settings.thoughtIntervalSeconds):'custom';panel.innerHTML=`<header class="thought-settings-head"><span><p class="label">THOUGHT SETTINGS</p><h2>생각 표시 방식</h2></span><em>${s.settings.thoughtAutoEnabled?'AUTO ON':'AUTO OFF'} · ${s.settings.thoughtClickEnabled?'CLICK ON':'CLICK OFF'}</em></header>${switchButton('thoughtAutoEnabled','Automatic Thoughts','캐릭터 화면에 머무르면 일정 간격마다 생각이 자동으로 나타납니다.',s.settings.thoughtAutoEnabled)}<label class="interval-field ${s.settings.thoughtAutoEnabled?'':'disabled'}"><span>Automatic interval</span><select id="thoughtInterval" ${s.settings.thoughtAutoEnabled?'':'disabled'}><option value="30" ${preset==='30'?'selected':''}>30초</option><option value="60" ${preset==='60'?'selected':''}>1분</option><option value="120" ${preset==='120'?'selected':''}>2분</option><option value="180" ${preset==='180'?'selected':''}>3분</option><option value="300" ${preset==='300'?'selected':''}>5분</option><option value="custom" ${preset==='custom'?'selected':''}>직접 설정</option></select><small>자동 Thought가 나타나는 간격입니다.</small></label><label id="thoughtCustomWrap" class="${preset==='custom'&&s.settings.thoughtAutoEnabled?'':'is-hidden'}"><span>직접 설정 (초)</span><input id="thoughtCustom" type="number" min="10" max="3600" value="${esc(s.settings.thoughtIntervalSeconds)}"></label>${switchButton('thoughtClickEnabled','Click character for thought','캐릭터 이미지를 클릭하면 현재 조건에 맞는 생각을 즉시 보여줍니다.',s.settings.thoughtClickEnabled)}${switchButton('thoughtPreferUnseen','Prefer new thoughts','아직 발견하지 않은 생각이 있다면 먼저 보여줍니다.',s.settings.thoughtPreferUnseen)}<div class="settings-reset-row"><span><strong>발견 기록 초기화</strong><small>작성한 Thought는 남고 발견 여부만 초기화됩니다.</small></span><button class="ghost-button danger" data-reset-thoughts>RESET</button></div>`;let box=$('[data-mystery-box-settings]');if(box)grid.insertBefore(panel,box);else grid.appendChild(panel)}
function pickerItems(s,type){return type==='event'?s.events.filter(e=>!e.hidden).map(e=>({id:e.id,name:e.name,desc:e.description})):s.memoryTagCatalog.map(x=>({id:x,name:x,desc:''}))}
function pickerButtons(s,type,values){let list=pickerItems(s,type),chosen=new Set(split(values)),empty=type==='event'?'등록된 Event가 없습니다.':'등록된 Memory Tag가 없습니다.';return list.length?list.map(e=>`<button type="button" class="select-pill ${chosen.has(e.id)?'selected':''}" data-pick-token="${esc(e.id)}" aria-pressed="${chosen.has(e.id)?'true':'false'}"><span>${esc(e.name)}</span>${e.desc?`<small>${esc(e.desc)}</small>`:''}</button>`).join(''):`<p class="muted picker-empty">${empty}</p>`}
function selectPills(type,inputId,values){let s=readState();return`<input type="hidden" id="${inputId}" value="${esc(split(values).join(', '))}"><div class="select-pill-grid" data-select-list="${type}" data-target-input="${inputId}">${pickerButtons(s,type,values)}</div><button type="button" class="text-link catalog-manage-button" ${type==='event'?'data-manage-events':'data-manage-memory-tags'}>${type==='event'?'EVENT 목록 관리':'MEMORY TAG 목록 관리'}</button>`}
function categoryOptions(s,selected){let set=new Set(selected);return(s.thoughtCategoryCatalog||[]).map(c=>`<button type="button" class="tag-option ${set.has(c.id)?'selected':''}" data-category-option="${esc(c.id)}" data-search-text="${esc((c.label+' '+c.id).toLowerCase())}" aria-pressed="${set.has(c.id)?'true':'false'}">${esc(c.label)}</button>`).join('')}
function selectedCategoryChips(s,selected){return selected.length?selected.map(id=>`<span class="editor-tag">${esc(categoryLabel(s,id))}<button type="button" data-remove-category="${esc(id)}" aria-label="Remove ${esc(categoryLabel(s,id))}">×</button></span>`).join(''):'<span class="tag-empty">선택된 카테고리 없음</span>'}
function selectedMoodChips(selected){return selected.length?selected.map(id=>`<span class="editor-tag">${esc(moodLabel(id))}<button type="button" data-remove-mood="${esc(id)}" aria-label="Remove ${esc(moodLabel(id))}">×</button></span>`).join(''):'<span class="tag-empty">모든 감정에서 등장</span>'}
function moodOptions(selected){let set=new Set(selected);return MOOD_CATALOG.map(m=>`<button type="button" class="tag-option ${set.has(m.id)?'selected':''}" data-mood-option="${m.id}" aria-pressed="${set.has(m.id)?'true':'false'}">${esc(m.label)}</button>`).join('')}
function categorySelector(s,selected){return`<input type="hidden" id="tCategories" value="${esc(selected.join(', '))}"><div id="tCategoryChips" class="selected-tag-row">${selectedCategoryChips(s,selected)}</div><details class="tag-selector"><summary>+ 카테고리 선택</summary><div class="tag-selector-panel"><input type="search" data-picker-search="category" placeholder="카테고리 검색"><div id="tCategoryOptions" class="tag-option-grid">${categoryOptions(s,selected)}</div><div class="tag-create-row"><input id="newCategoryLabel" placeholder="새 카테고리 이름"><button type="button" class="ghost-button" data-add-category-inline>+ 새 카테고리</button></div><button type="button" class="text-link" data-manage-categories>카테고리 관리</button></div></details>`}
function moodSelector(selected){return`<input type="hidden" id="tMoods" value="${esc(selected.join(', '))}"><div id="tMoodChips" class="selected-tag-row">${selectedMoodChips(selected)}</div><details class="tag-selector"><summary>+ 감정 선택</summary><div class="tag-selector-panel"><div id="tMoodOptions" class="tag-option-grid">${moodOptions(selected)}</div><button type="button" class="text-link" data-clear-moods>ANY / 모든 감정</button></div></details><small>감정을 선택하지 않으면 모든 감정 상태에서 등장할 수 있습니다.</small>`}
function frequencySelect(current,inputId='tFreq',label='Thought frequency'){let selected=normalizeFrequency(current),options=[['rare','드물게','다른 항목보다 적게 등장'],['normal','보통','기본 빈도로 등장'],['common','자주','다른 항목보다 자주 등장']];return`<input type="hidden" id="${esc(inputId)}" value="${selected}"><div class="frequency-picker" role="group" aria-label="${esc(label)}">${options.map(([value,name,help])=>`<button type="button" class="frequency-option ${selected===value?'selected':''}" data-pick-frequency="${value}" data-frequency-target="${esc(inputId)}" aria-pressed="${selected===value?'true':'false'}"><strong>${name}</strong><small>${help}</small></button>`).join('')}</div>`}
function patchThoughtEditor(){let old=$('#tCat')?.closest('.editor-card');if(!old||old.dataset.v35ThoughtEditor)return;let s=readState(),cid=s.active,t=s.thoughts.find(x=>x.id===s.draft?.thought)||normalizeThought({characterId:cid,id:'',categories:[],requiredMoods:[],frequency:'normal'}),cats=thoughtCategories(t),moods=thoughtMoods(t),advanced=!!(moods.length||t.requiredFlags||t.blockedFlags||t.requiredMemoryTags);old.dataset.v35ThoughtEditor='yes';old.innerHTML=`<header class="thought-editor-head"><span><p class="label">THOUGHT EDITOR</p><h2>${t.id&&s.thoughts.some(x=>x.id===t.id)?'생각 수정':'새 생각 작성'}</h2></span><small>${esc(characterName(s,cid))}</small></header><section class="basic-block"><h3>BASIC</h3><div class="form-grid"><div class="full editor-field"><div class="field-heading"><strong>Categories</strong><small>생각의 주제와 분류입니다. 여러 개 선택할 수 있습니다.</small></div>${categorySelector(s,cats)}</div><label>Required Heart<input id="tReq" type="number" min="0" max="100" value="${esc(t.requiredAffection)}"><small>이 호감도 이상에서만 나타납니다.</small></label><label class="full">Text<textarea id="tText" rows="5" placeholder="캐릭터가 속으로 하는 생각을 적어 주세요.">${esc(t.text)}</textarea></label></div></section><details class="sub-editor thought-advanced" ${advanced?'open':''}><summary><span>ADVANCED CONDITIONS</span><small>필요할 때만 설정하세요</small></summary><div class="form-grid"><div class="full editor-field"><div class="field-heading"><strong>Appears in moods</strong><small>선택한 감정 상태 중 하나일 때 이 생각이 등장할 수 있습니다.</small></div>${moodSelector(moods)}</div><label class="full condition-picker"><strong>Required Events</strong><small>선택한 사건을 모두 경험한 뒤에만 나타납니다.</small>${selectPills('event','tFlags',t.requiredFlags)}</label><label class="full condition-picker"><strong>Blocked Events</strong><small>선택한 사건 중 하나라도 발생하면 더 이상 나타나지 않습니다.</small>${selectPills('event','tBlock',t.blockedFlags)}</label><label class="full condition-picker"><strong>Required Memories</strong><small>선택한 기억 태그를 모두 가진 뒤에만 나타납니다.</small>${selectPills('memory','tMem',t.requiredMemoryTags)}</label><label class="full">Frequency${frequencySelect(t.frequency)}<small>조건을 만족했을 때 이 생각이 얼마나 자주 등장할지 설정합니다.</small></label></div><aside class="flag-help"><strong>Event와 Memory</strong><p><b>Event</b>는 게임에서 특정 사건이 일어났는지 기록하는 상태이고, <b>Memory</b>는 대화나 경험을 통해 기록된 기억입니다.</p></aside></details><div class="button-row thought-editor-actions"><button class="gold-button" data-save-thought-v35>${t.id&&s.thoughts.some(x=>x.id===t.id)?'SAVE CHANGES':'SAVE'}</button><button class="ghost-button" data-new="thought">NEW THOUGHT</button></div>`;patchSavedThoughtList(true)}
function patchMysteryRewardEditor(){let input=$('#bFreq');if(!input||input.dataset.v39Frequency)return;let label=input.closest('label');if(!label)return;let frequency=normalizeFrequency(input.value);input.dataset.v39Frequency='yes';label.classList.add('box-frequency-field');label.innerHTML=`<strong>Draw Frequency</strong>${frequencySelect(frequency,'bFreq','Mystery Box draw frequency')}<small>보상 등급과 별개로 이 Reward가 전체 보상 중 등장하는 상대 빈도입니다.</small>`}
function thoughtSummaryHtml(s,t){let cats=thoughtCategories(t),moods=thoughtMoods(t),shown=cats.slice(0,3),more=cats.length-shown.length,events=split(t.requiredFlags).map(id=>eventName(s,id));return`<div class="thought-list-tags">${shown.map(id=>`<span>${esc(categoryLabel(s,id))}</span>`).join('')}${more?`<b>+${more}</b>`:''}</div><p class="thought-list-mood">Mood: ${moods.length?moods.map(moodLabel).join(' 또는 '):'모든 감정'}</p><small>♥ ${Number(t.requiredAffection||0)} · ${esc(FREQUENCY_LABELS[normalizeFrequency(t.frequency,t.probability)])}${events.length?` · Event: ${esc(events.join(', '))}`:''}</small>`}
function patchSavedThoughtList(force=false){let s=readState(),panels=$$('.saved-panel').filter(p=>/Thoughts/i.test(p.textContent)||p.dataset.v35ThoughtList);panels.forEach(panel=>{if(panel.dataset.v35ThoughtList&&!force)return;let items=s.thoughts.filter(t=>t.characterId===s.active);panel.dataset.v35ThoughtList='yes';panel.innerHTML=`<p class="label">Thoughts</p>${items.length?items.map(t=>`<div class="saved-card thought-saved-card"><div><strong>${esc(short(t.text||'Thought',68))}</strong>${thoughtSummaryHtml(s,t)}</div><div><button data-edit-type="thought" data-edit-id="${esc(t.id)}">EDIT</button><button data-del="thought:${esc(t.id)}">DELETE</button></div></div>`).join(''):'<p class="empty-state">아직 저장된 Thought가 없습니다.</p>'}`})}
function enhanceLegacyInput(input,type,title,help){if(input.dataset.v35Picker)return;let label=input.closest('label');if(!label)return;let value=input.value;input.dataset.v35Picker='yes';input.type='hidden';label.classList.add('picker-field');Array.from(label.childNodes).filter(n=>n.nodeType===Node.TEXT_NODE).forEach(n=>n.textContent='');let titleNode=document.createElement('div');titleNode.className='picker-title';titleNode.innerHTML=`<strong>${esc(title)}</strong><small>${esc(help)}</small>`;label.insertBefore(titleNode,input);let wrap=document.createElement('div');wrap.className='legacy-picker-wrap';wrap.innerHTML=`<div class="select-pill-grid" data-select-list="${type}" data-target-input="${esc(input.id)}">${pickerButtons(readState(),type,value)}</div><button type="button" class="text-link catalog-manage-button" ${type==='event'?'data-manage-events':'data-manage-memory-tags'}>${type==='event'?'EVENT 목록 관리':'MEMORY TAG 목록 관리'}</button>`;label.appendChild(wrap)}
function patchDialoguePickers(){let fields=[['sFlags','event','Required Event','선택한 사건을 경험한 뒤에만 이 대화가 열립니다.'],['sBlocked','event','Blocked Event','선택한 사건 중 하나라도 발생하면 이 대화가 열리지 않습니다.'],['sMem','memory','Required Memory','선택한 기억 태그를 모두 가진 뒤에만 이 대화가 열립니다.'],['gReqFlags','event','Required Event','선물을 줄 수 있게 되는 사건을 선택하세요.'],['gBlocked','event','Blocked Event','선물을 막는 사건을 선택하세요.'],['gReqMem','memory','Required Memory','선물에 필요한 기억을 선택하세요.'],['gASet','event','Choice A Event','A 선택 뒤 발생할 사건을 선택하세요.'],['gARem','event','Choice A Event 종료','A 선택 뒤 해제할 사건을 선택하세요.'],['gBSet','event','Choice B Event','B 선택 뒤 발생할 사건을 선택하세요.'],['gBRem','event','Choice B Event 종료','B 선택 뒤 해제할 사건을 선택하세요.'],['gSet','event','Gift Event','선물 뒤 발생할 사건을 선택하세요.'],['gRemove','event','Gift Event 종료','선물 뒤 해제할 사건을 선택하세요.'],['gTags','memory','Memory Tags','선물로 생기는 기억에 붙일 태그를 선택하세요.']];for(let n=1;n<=5;n++)fields.push([`c${n}flags`,'event','Events triggered after this choice','이 선택을 하면 발생할 사건을 선택하세요.'],[`c${n}remove`,'event','Events ended after this choice','이 선택을 하면 해제할 사건을 선택하세요.'],[`c${n}rflags`,'event','Required Event','이 사건을 경험한 뒤에만 선택지가 열립니다.'],[`c${n}bflags`,'event','Blocked Event','이 사건이 발생하면 선택지가 잠깁니다.'],[`c${n}rmem`,'memory','Required Memory','선택지에 필요한 기억을 선택하세요.'],[`c${n}tags`,'memory','Memory Tags','이 선택으로 생기는 기억의 태그를 선택하세요.']);fields.forEach(([inputId,type,title,help])=>{let input=$('#'+inputId);if(input)enhanceLegacyInput(input,type,title,help)})}
function patchMemoryEditorPicker(){let input=$('#mTags');if(input)enhanceLegacyInput(input,'memory','Memory Tags','이 기억을 분류할 태그를 선택하세요.')}
function saveThoughtFromEditor(){let s=readState(),cid=s.active,old=s.thoughts.find(x=>x.id===s.draft?.thought)||{},wasExisting=!!old.id,text=($('#tText')?.value||'').trim();if(!text){toast('THOUGHT TEXT REQUIRED','생각 내용을 입력해 주세요.');$('#tText')?.focus();return}let categories=split($('#tCategories')?.value||''),requiredMoods=split($('#tMoods')?.value||'').map(normalizeMoodId).filter(Boolean),frequency=normalizeFrequency($('#tFreq')?.value||'normal'),t=normalizeThought({...old,id:old.id||uid('thought'),characterId:cid,categories,requiredMoods,category:old.category||categories[0]||'',requiredMood:requiredMoods.length===1?requiredMoods[0].toUpperCase():'ANY',requiredAffection:Number($('#tReq')?.value||0),requiredFlags:$('#tFlags')?.value||'',blockedFlags:$('#tBlock')?.value||'',requiredMemoryTags:$('#tMem')?.value||'',frequency,appearanceWeight:FREQUENCY_WEIGHTS[frequency],text});let i=s.thoughts.findIndex(x=>x.id===t.id);if(i>=0)s.thoughts[i]=t;else s.thoughts.unshift(t);s.draft={...(s.draft||{}),thought:t.id};writeState(s,{clearDirty:true});let saved=readState().thoughts.find(x=>x.id===t.id);if(!saved||saved.frequency!==frequency||JSON.stringify(thoughtCategories(saved))!==JSON.stringify(categories)||JSON.stringify(thoughtMoods(saved))!==JSON.stringify(requiredMoods)){toast('SAVE FAILED','저장값을 다시 확인해 주세요.');return}toast(wasExisting?'THOUGHT UPDATED':'THOUGHT SAVED');patchSavedThoughtList(true);let button=$('[data-save-thought-v35]');if(button)button.textContent='SAVE CHANGES';let title=$('.thought-editor-head h2');if(title)title.textContent='생각 수정'}
function includesToken(value,token){return split(value).includes(token)}
function eventUseCount(s,eventId){let count=s.flags&&Object.prototype.hasOwnProperty.call(s.flags,eventId)?1:0;(s.thoughts||[]).forEach(t=>['requiredFlags','blockedFlags'].forEach(k=>{if(includesToken(t[k],eventId))count++}));(s.gifts||[]).forEach(g=>['requiredFlags','blockedFlags','setFlags','removeFlags','choiceASetFlags','choiceARemoveFlags','choiceBSetFlags','choiceBRemoveFlags'].forEach(k=>{if(includesToken(g[k],eventId))count++}));(s.dialogues||s.interactions||[]).forEach(sc=>{['requiredFlags','blockedFlags'].forEach(k=>{if(includesToken(sc[k],eventId))count++});(sc.nodes||[]).forEach(n=>(n.choices||[]).forEach(ch=>['requiredFlags','blockedFlags','setFlags','removeFlags'].forEach(k=>{if(includesToken(ch[k],eventId))count++}))) });return count}
function memoryTagUseCount(s,tag){let count=0;(s.memories||[]).forEach(m=>{if(includesToken(m.tags,tag))count++});(s.thoughts||[]).forEach(t=>{if(includesToken(t.requiredMemoryTags,tag))count++});return count}
function categoryUseCount(s,id){return(s.thoughts||[]).filter(t=>thoughtCategories(t).includes(id)).length}
function managerRow(name,description,count,actions=''){return`<article><span><strong>${esc(name)}</strong><small>${description?esc(description)+' · ':''}${count?`${count}곳에서 사용 중`:'아직 사용되지 않음'}</small></span><span>${actions}</span></article>`}
function refreshEventPickers(){let state=readState();$$('[data-select-list="event"][data-target-input]').forEach(grid=>{let input=$('#'+CSS.escape(grid.dataset.targetInput||''));grid.innerHTML=pickerButtons(state,'event',input?.value||'')})}
function showEventManager(editId=''){let s=readState(),editing=s.events.find(e=>e.id===editId)||{};showModal(`<div class="catalog-manager"><p class="label">EVENT MANAGER</p><h2>사건 목록</h2><div class="catalog-list">${s.events.length?s.events.map(e=>{let used=eventUseCount(s,e.id);return managerRow(e.name,e.description,used,`<button class="text-link" data-edit-event="${esc(e.id)}">수정</button><button class="text-link danger" data-delete-event="${esc(e.id)}" ${used?'disabled':''}>삭제</button>`)}).join(''):'<p class="empty-state">아직 등록된 Event가 없습니다.</p>'}</div><hr><input type="hidden" id="eventEditId" value="${esc(editing.id||'')}"><label>Event 이름<input id="eventName" value="${esc(editing.name||'')}"></label><label>설명<textarea id="eventDesc" rows="2">${esc(editing.description||'')}</textarea></label><div class="button-row"><button class="gold-button" data-save-event>${editing.id?'SAVE EVENT':'ADD EVENT'}</button><button class="ghost-button" data-modal-close>CLOSE</button></div></div>`)}
function showCategoryManager(){let s=readState();showModal(`<div class="catalog-manager"><p class="label">CATEGORY MANAGER</p><h2>Thought 카테고리</h2><div class="catalog-list">${(s.thoughtCategoryCatalog||[]).map(c=>{let count=categoryUseCount(s,c.id);return managerRow(c.label,c.locked?'기본 카테고리':'사용자 카테고리',count,c.locked?'':`<button class="text-link danger" data-delete-category="${esc(c.id)}" ${count?'disabled':''}>삭제</button>`)}).join('')}</div><hr><label>새 Category<input id="categoryName" placeholder="예: 추락"></label><div class="button-row"><button class="gold-button" data-save-category>ADD CATEGORY</button><button class="ghost-button" data-modal-close>CLOSE</button></div></div>`)}
function showMemoryTagManager(){let s=readState();showModal(`<div class="catalog-manager"><p class="label">MEMORY TAG MANAGER</p><h2>기억 태그</h2><div class="catalog-list">${s.memoryTagCatalog.length?s.memoryTagCatalog.map(tag=>{let count=memoryTagUseCount(s,tag);return managerRow(tag,'',count,`<button class="text-link danger" data-delete-memory-tag="${esc(tag)}" ${count?'disabled':''}>삭제</button>`)}).join(''):'<p class="empty-state">아직 등록된 Memory Tag가 없습니다.</p>'}</div><hr><label>새 Memory Tag<input id="memoryTagName"></label><div class="button-row"><button class="gold-button" data-save-memory-tag>ADD MEMORY TAG</button><button class="ghost-button" data-modal-close>CLOSE</button></div></div>`)}
function uniqueEventId(s,name){let base=slug(name,'event'),next=base,n=2;while(s.events.some(e=>e.id===next))next=base+'-'+n++;return next}
function uniqueCategoryId(s,label){let base=slug(label,'category'),next=base,n=2;while((s.thoughtCategoryCatalog||[]).some(c=>c.id===next))next=base+'-'+n++;return next}
function saveEvent(){let id=$('#eventEditId')?.value||'',name=($('#eventName')?.value||'').trim(),description=$('#eventDesc')?.value||'';if(!name){toast('EVENT NAME REQUIRED');return}let savedId=id;updateState(s=>{let nextId=id||uniqueEventId(s,name),next={id:nextId,name,description,hidden:false},i=s.events.findIndex(e=>e.id===nextId);savedId=nextId;if(i>=0)s.events[i]=next;else s.events.push(next)});let saved=readState().events.find(e=>e.id===savedId);if(!saved){toast('EVENT SAVE FAILED','저장값을 확인해 주세요.');return}refreshEventPickers();toast(id?'EVENT UPDATED':'EVENT SAVED');showEventManager(savedId)}
function deleteEvent(id){let s=readState();if(eventUseCount(s,id)){toast('EVENT IS IN USE');return}updateState(x=>{x.events=x.events.filter(e=>e.id!==id)});refreshEventPickers();toast('EVENT DELETED');showEventManager()}
function createCategory(label,selectNow=false){label=String(label||'').trim();if(!label){toast('CATEGORY NAME REQUIRED');return''}let created='';updateState(s=>{let existing=(s.thoughtCategoryCatalog||[]).find(c=>c.label===label);if(existing){created=existing.id;return}created=uniqueCategoryId(s,label);s.thoughtCategoryCatalog.push({id:created,label,locked:false})});if(selectNow&&created){let input=$('#tCategories'),set=new Set(split(input?.value||''));set.add(created);if(input){input.value=[...set].join(', ');input.dispatchEvent(new Event('input',{bubbles:true}))}refreshCategorySelector()}return created}
function saveCategory(){let id=createCategory($('#categoryName')?.value||'',false);if(id){toast('CATEGORY SAVED');showCategoryManager()}}
function deleteCategory(id){let s=readState(),cat=s.thoughtCategoryCatalog.find(c=>c.id===id);if(!cat||cat.locked||categoryUseCount(s,id)){toast('CATEGORY IS IN USE');return}updateState(x=>{x.thoughtCategoryCatalog=x.thoughtCategoryCatalog.filter(c=>c.id!==id)});toast('CATEGORY DELETED');showCategoryManager()}
function saveMemoryTag(){let tag=($('#memoryTagName')?.value||'').trim();if(!tag){toast('MEMORY TAG REQUIRED');return}updateState(s=>{if(!s.memoryTagCatalog.includes(tag))s.memoryTagCatalog.push(tag)});toast('MEMORY TAG SAVED');showMemoryTagManager()}
function deleteMemoryTag(tag){let s=readState();if(memoryTagUseCount(s,tag)){toast('MEMORY TAG IS IN USE');return}updateState(x=>{x.memoryTagCatalog=x.memoryTagCatalog.filter(t=>t!==tag)});toast('MEMORY TAG DELETED');showMemoryTagManager()}
function updateInputToken(inputId,token){let input=$('#'+CSS.escape(inputId));if(!input)return;let set=new Set(split(input.value));set.has(token)?set.delete(token):set.add(token);input.value=[...set].join(', ');input.dispatchEvent(new Event('input',{bubbles:true}));let box=input.closest('label')||document;box.querySelectorAll('[data-pick-token]').forEach(btn=>{let selected=set.has(btn.dataset.pickToken);btn.classList.toggle('selected',selected);btn.setAttribute('aria-pressed',String(selected))})}
function setEditorList(id,values){let input=$('#'+id);if(!input)return;input.value=[...new Set(values.filter(Boolean))].join(', ');input.dispatchEvent(new Event('input',{bubbles:true}))}
function refreshCategorySelector(){let s=readState(),input=$('#tCategories');if(!input)return;let selected=split(input.value),chips=$('#tCategoryChips'),opts=$('#tCategoryOptions');if(chips)chips.innerHTML=selectedCategoryChips(s,selected);if(opts)opts.innerHTML=categoryOptions(s,selected)}
function refreshMoodSelector(){let input=$('#tMoods');if(!input)return;let selected=split(input.value).map(normalizeMoodId).filter(Boolean),chips=$('#tMoodChips'),opts=$('#tMoodOptions');if(chips)chips.innerHTML=selectedMoodChips(selected);if(opts)opts.innerHTML=moodOptions(selected)}
function toggleCategory(id){let set=new Set(split($('#tCategories')?.value||''));set.has(id)?set.delete(id):set.add(id);setEditorList('tCategories',[...set]);refreshCategorySelector()}
function toggleMood(id){id=normalizeMoodId(id);let set=new Set(split($('#tMoods')?.value||'').map(normalizeMoodId).filter(Boolean));set.has(id)?set.delete(id):set.add(id);setEditorList('tMoods',[...set]);refreshMoodSelector()}
function updateThoughtSetting(key,value){updateState(s=>{s.settings[key]=value});toast('THOUGHT SETTINGS SAVED');patchSettings();scheduleAutoThought(true)}
function patchCollectionModal(){let s=readState(),root=$('#modalRoot');if(!root||!root.innerHTML.includes('collection-detail-modal'))return;let title=root.querySelector('.item-detail h2')?.textContent,item=s.collectionItems.find(i=>itemTitle(i)===title);if(!item||!s.ownedItems.includes(item.id))return;let messages=s.rewards.filter(r=>r.itemId===item.id&&String(r.body||'').trim()),detail=root.querySelector('.item-detail');if(detail&&!detail.querySelector('.collection-message')&&messages.length){let section=document.createElement('section');section.innerHTML=`<h3>Body / Character Message</h3>${messages.map(r=>`<article class="collection-message"><strong>${esc(r.title||r.name||'Reward')}</strong><p>${esc(r.body||r.message||'')}</p>${r.characterId?`<small>${esc(characterName(s,r.characterId))}</small>`:''}</article>`).join('')}`;detail.appendChild(section)}}
function afterRender(){patchNav();patchHome();patchSettings();patchThoughtEditor();patchMysteryRewardEditor();patchDialoguePickers();patchMemoryEditorPicker();patchSavedThoughtList();patchCollectionModal();renderExternalPage();scheduleAutoThought()}
function handleClick(e){let target=e.target;if(!(target instanceof Element))return;if(target.closest('[data-thought]')){e.stopImmediatePropagation();let s=readState();if(s.settings.thoughtClickEnabled===false)return;let nowMs=Date.now();if(nowMs-clickCooldown<450)return;clickCooldown=nowMs;showCharacterThought(target.closest('[data-thought]').dataset.thought,'click');return}if(target.closest('[data-open-thoughts]')){e.preventDefault();e.stopImmediatePropagation();setRewardPage('thoughts');renderThoughtPage();return}if(target.closest('[data-open-mystery]')){e.preventDefault();e.stopImmediatePropagation();setRewardPage('mystery');renderMysteryPage();return}if(target.closest('[data-page]')){clearRewardPage();return}let group=target.closest('[data-thought-group]')?.dataset.thoughtGroup;if(group){e.preventDefault();e.stopImmediatePropagation();let u=readUI();u.openThoughts[group]=!u.openThoughts[group];writeUI(u);renderThoughtPage();return}let tid=target.closest('[data-thought-card]')?.dataset.thoughtCard;if(tid){e.preventDefault();e.stopImmediatePropagation();showThoughtDetail(tid);return}if(target.closest('[data-box-page-open]')){e.preventDefault();e.stopImmediatePropagation();openMysteryBox();return}if(target.closest('[data-view-last-box]')){e.preventDefault();e.stopImmediatePropagation();let s=readState();if(s.box.lastResult)rewardModal(s.box.lastResult);return}let bm=target.closest('[data-box-mode-v35]')?.dataset.boxModeV35;if(bm){e.preventDefault();e.stopImmediatePropagation();updateState(s=>{s.settings.mysteryBoxMode=bm==='unlimited'?'unlimited':'daily'});toast('SAVED');renderMysteryPage();return}if(target.closest('[data-reset-col]')){e.preventDefault();e.stopImmediatePropagation();resetModal('collection');return}if(target.closest('[data-reset-thoughts]')){e.preventDefault();e.stopImmediatePropagation();resetModal('thought');return}if(target.closest('[data-reset-box]')){e.preventDefault();e.stopImmediatePropagation();resetModal('box');return}if(target.closest('[data-confirm-reset-collection]')){e.preventDefault();e.stopImmediatePropagation();resetCollectionProgress();$('#modalRoot').innerHTML='';return}if(target.closest('[data-confirm-reset-thoughts]')){e.preventDefault();e.stopImmediatePropagation();resetThoughtArchive();$('#modalRoot').innerHTML='';return}if(target.closest('[data-confirm-reset-box]')){e.preventDefault();e.stopImmediatePropagation();resetMysteryBox();$('#modalRoot').innerHTML='';return}let toggle=target.closest('[data-thought-toggle]');if(toggle){e.preventDefault();e.stopImmediatePropagation();let key=toggle.dataset.thoughtToggle,s=readState();updateThoughtSetting(key,!s.settings[key]);return}let freq=target.closest('[data-pick-frequency]');if(freq){e.preventDefault();e.stopImmediatePropagation();let value=normalizeFrequency(freq.dataset.pickFrequency),targetId=freq.dataset.frequencyTarget||'tFreq',input=$('#'+CSS.escape(targetId));if(input){input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}))}freq.closest('.frequency-picker')?.querySelectorAll('[data-pick-frequency]').forEach(btn=>{let selected=btn===freq;btn.classList.toggle('selected',selected);btn.setAttribute('aria-pressed',String(selected))});return}let catOpt=target.closest('[data-category-option]');if(catOpt){e.preventDefault();e.stopImmediatePropagation();toggleCategory(catOpt.dataset.categoryOption);return}let moodOpt=target.closest('[data-mood-option]');if(moodOpt){e.preventDefault();e.stopImmediatePropagation();toggleMood(moodOpt.dataset.moodOption);return}let rmCat=target.closest('[data-remove-category]')?.dataset.removeCategory;if(rmCat){e.preventDefault();e.stopImmediatePropagation();let vals=split($('#tCategories')?.value||'').filter(x=>x!==rmCat);setEditorList('tCategories',vals);refreshCategorySelector();return}let rmMood=target.closest('[data-remove-mood]')?.dataset.removeMood;if(rmMood){e.preventDefault();e.stopImmediatePropagation();let vals=split($('#tMoods')?.value||'').map(normalizeMoodId).filter(x=>x&&x!==rmMood);setEditorList('tMoods',vals);refreshMoodSelector();return}if(target.closest('[data-clear-moods]')){e.preventDefault();e.stopImmediatePropagation();setEditorList('tMoods',[]);refreshMoodSelector();return}if(target.closest('[data-add-category-inline]')){e.preventDefault();e.stopImmediatePropagation();let field=$('#newCategoryLabel'),id=createCategory(field?.value||'',true);if(id&&field)field.value='';if(id)toast('CATEGORY ADDED');return}let token=target.closest('[data-pick-token]');if(token){e.preventDefault();e.stopImmediatePropagation();let grid=token.closest('[data-target-input]');if(grid)updateInputToken(grid.dataset.targetInput,token.dataset.pickToken);return}if(target.closest('[data-manage-events]')){e.preventDefault();e.stopImmediatePropagation();showEventManager();return}if(target.closest('[data-manage-categories]')){e.preventDefault();e.stopImmediatePropagation();showCategoryManager();return}if(target.closest('[data-manage-memory-tags]')){e.preventDefault();e.stopImmediatePropagation();showMemoryTagManager();return}let edit=target.closest('[data-edit-event]')?.dataset.editEvent;if(edit){e.preventDefault();e.stopImmediatePropagation();showEventManager(edit);return}let del=target.closest('[data-delete-event]')?.dataset.deleteEvent;if(del){e.preventDefault();e.stopImmediatePropagation();deleteEvent(del);return}let delCat=target.closest('[data-delete-category]')?.dataset.deleteCategory;if(delCat){e.preventDefault();e.stopImmediatePropagation();deleteCategory(delCat);return}let memoryTag=target.closest('[data-delete-memory-tag]')?.dataset.deleteMemoryTag;if(memoryTag){e.preventDefault();e.stopImmediatePropagation();deleteMemoryTag(memoryTag);return}if(target.closest('[data-save-event]')){e.preventDefault();e.stopImmediatePropagation();saveEvent();return}if(target.closest('[data-save-category]')){e.preventDefault();e.stopImmediatePropagation();saveCategory();return}if(target.closest('[data-save-memory-tag]')){e.preventDefault();e.stopImmediatePropagation();saveMemoryTag();return}if(target.closest('[data-save-thought-v35]')){e.preventDefault();e.stopImmediatePropagation();saveThoughtFromEditor();return}if(target.closest('[data-modal-close]')){let root=$('#modalRoot');if(root)root.innerHTML='';return}}
function handleChange(e){let t=e.target;if(!(t instanceof Element))return;if(t.id==='thoughtInterval'){let val=t.value,seconds=val==='custom'?Number($('#thoughtCustom')?.value||60):Number(val);updateState(s=>{s.settings.thoughtIntervalSeconds=clamp(seconds,10,3600)});toast('THOUGHT SETTINGS SAVED');patchSettings();scheduleAutoThought(true);return}if(t.id==='thoughtCustom'){updateState(s=>{s.settings.thoughtIntervalSeconds=clamp(t.value,10,3600)});toast('THOUGHT SETTINGS SAVED');scheduleAutoThought(true);return}}
function handleInput(e){let t=e.target;if(!(t instanceof Element))return;if(t.matches('[data-picker-search="category"]')){e.stopImmediatePropagation();let q=t.value.toLowerCase().trim();$$('#tCategoryOptions [data-category-option]').forEach(btn=>{btn.hidden=!!q&&!String(btn.dataset.searchText||'').includes(q)});return}}
function handleKey(e){let tag=e.target&&e.target.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT')return;if(e.key==='Escape'){let u=readUI();if(u.page){u.page='';writeUI(u)}}}
function observeMainApp(){let app=$('#app');if(!app)return;let queued=false;new MutationObserver(ms=>{if(!ms.some(m=>m.target===app))return;if(queued)return;queued=true;queueMicrotask(()=>{queued=false;afterRender()})}).observe(app,{childList:true})}
